from typing import Mapping, Optional

def witness_scale(profile: Mapping[float, float], epsilon: float) -> Optional[float]:
    """Return a sampled positive scale below the threshold, if one exists."""
    if epsilon <= 0 or any(r <= 0 for r in profile):
        raise ValueError("epsilon and radii must be positive")
    return next((r for r, value in sorted(profile.items(), reverse=True)
                 if value < epsilon), None)

if __name__ == "__main__":
    eps = 0.1
    profiles = {
        "a": {1.0: .42, .5: .18, .25: .08, .125: .04},
        "b": {1.0: .31, .5: .21, .25: .14, .125: .11},
    }
    for point, profile in profiles.items():
        witness = witness_scale(profile, eps)
        print(point, "certified regular" if witness is not None else "unresolved",
              "witness:", witness)

