from typing import Sequence

def conservative_completion(values: Sequence[float]) -> list[float]:
    """Append the unique final entry that makes the finite sum zero."""
    return [*values, -sum(values)]

if __name__ == "__main__":
    for trial in ([1., 2., -1.], [3.5, -.5], [-2., -1., 4., 8.]):
        completed = conservative_completion(trial)
        print(completed, "total =", sum(completed))

